<?php
namespace OpenLMS\Controllers;

use OpenLMS\Core\Auth;
use OpenLMS\Core\Csrf;
use OpenLMS\Core\Database;
use OpenLMS\Policies\CoursePolicy;
use OpenLMS\Services\UploadService;

trait ProjectActionsTrait
{
    private static function submitProject(array $p,array $u):void{$now=gmdate('Y-m-d H:i:s');if($p['starts_at']&&$now<$p['starts_at'])throw new \RuntimeException('Submissions have not opened yet.');$late=$p['deadline_at']&&$now>$p['deadline_at'];if($late&&$p['late_policy']==='reject')throw new \RuntimeException('The submission deadline has passed.');$gid=null;if($p['project_type']==='group'){$st=Database::connection()->prepare('SELECT pg.id FROM project_groups pg JOIN project_group_members gm ON gm.group_id=pg.id WHERE pg.project_id=? AND gm.user_id=?');$st->execute([(int)$p['id'],(int)$u['id']]);$gid=(int)($st->fetchColumn()?:0);if(!$gid)throw new \RuntimeException('You are not assigned to a project group.');}$pdo=Database::connection();if($gid){$st=$pdo->prepare('SELECT COALESCE(MAX(version_no),0) FROM project_submissions WHERE project_id=? AND group_id=?');$st->execute([(int)$p['id'],$gid]);}else{$st=$pdo->prepare('SELECT COALESCE(MAX(version_no),0) FROM project_submissions WHERE project_id=? AND user_id=? AND group_id IS NULL');$st->execute([(int)$p['id'],(int)$u['id']]);}$last=(int)$st->fetchColumn();if($last>0&&!(int)$p['resubmission_allowed'])throw new \RuntimeException('Resubmission is disabled.');$files=$_FILES['files']??null;if(!$files||!isset($files['name'])||!is_array($files['name']))throw new \RuntimeException('Choose at least one file.');$count=count($files['name']);if(!(int)$p['allow_multiple_files']&&$count>1)throw new \RuntimeException('Only one file is allowed.');$pdo->prepare("INSERT INTO project_submissions (project_id,user_id,version_no,status,submitted_at,group_id,is_late) VALUES (?,?,?,'submitted',?,?,?)")->execute([(int)$p['id'],(int)$u['id'],$last+1,$now,$gid?:null,$late?1:0]);$sid=(int)$pdo->lastInsertId();$allowed=parse_csv_list((string)$p['allowed_extensions']);$stored=0;try{for($i=0;$i<$count;$i++){$file=[];foreach(['name','type','tmp_name','error','size'] as $k)$file[$k]=$files[$k][$i]??null;if((int)$file['error']===UPLOAD_ERR_NO_FILE)continue;[$ok,$result]=UploadService::storeProjectSubmissionFile($sid,$file,$allowed,(int)$p['max_upload_bytes']);if(!$ok)throw new \RuntimeException((string)$result);$stored++;}if($stored<1)throw new \RuntimeException('No valid file was uploaded.');$pdo->prepare('INSERT INTO project_submission_events (submission_id,actor_user_id,event_type,details,created_at) VALUES (?,?,?,?,?)')->execute([$sid,(int)$u['id'],'submitted','Version '.($last+1),$now]);Auth::audit('project.submitted','Project submission uploaded',(int)$u['id'],'project_submission',$sid);}catch(\Throwable $e){foreach(self::submissionFiles($sid) as $f)UploadService::deleteSubmissionFile($f);$pdo->prepare('DELETE FROM project_submissions WHERE id=?')->execute([$sid]);throw $e;}}
    private static function upsertGrade(array $s,array $p,float $marks,int $grader):void{$pdo=Database::connection();$userId=(int)$s['user_id'];$st=$pdo->prepare("SELECT id FROM grades WHERE user_id=? AND item_type='project' AND item_id=?");$st->execute([$userId,(int)$p['id']]);$id=$st->fetchColumn();$now=gmdate('Y-m-d H:i:s');if($id)$pdo->prepare('UPDATE grades SET marks=?,max_marks=?,graded_by=?,graded_at=? WHERE id=?')->execute([$marks,(float)$p['max_marks'],$grader,$now,(int)$id]);else$pdo->prepare("INSERT INTO grades (user_id,course_id,item_type,item_id,marks,max_marks,graded_by,graded_at) VALUES (?,?, 'project',?,?,?,?,?)")->execute([$userId,(int)$p['course_id'],(int)$p['id'],$marks,(float)$p['max_marks'],$grader,$now]);if(!empty($s['group_id'])){$st=$pdo->prepare('SELECT user_id FROM project_group_members WHERE group_id=?');$st->execute([(int)$s['group_id']]);foreach($st->fetchAll(\PDO::FETCH_COLUMN) as $member){if((int)$member===$userId)continue;$existing=$pdo->prepare("SELECT id FROM grades WHERE user_id=? AND item_type='project' AND item_id=?");$existing->execute([(int)$member,(int)$p['id']]);$gid=$existing->fetchColumn();if($gid)$pdo->prepare('UPDATE grades SET marks=?,max_marks=?,graded_by=?,graded_at=? WHERE id=?')->execute([$marks,(float)$p['max_marks'],$grader,$now,(int)$gid]);else$pdo->prepare("INSERT INTO grades (user_id,course_id,item_type,item_id,marks,max_marks,graded_by,graded_at) VALUES (?,?, 'project',?,?,?,?,?)")->execute([(int)$member,(int)$p['course_id'],(int)$p['id'],$marks,(float)$p['max_marks'],$grader,$now]);}}}
}
